def solve(inputs: dict) -> float:
    a = inputs['A']
    b = inputs['B']
    c = inputs['C']
    d = inputs['D']
    mod = inputs['MOD']
    k = inputs['K']

    # Define matrix multiplication with modulo
    def mat_mult(M1, M2, mod):
        result = [[0, 0], [0, 0]]
        for i in range(2):
            for j in range(2):
                for l in range(2):
                    result[i][j] = (result[i][j] + M1[i][l] * M2[l][j]) % mod
        return result

    # Fast matrix exponentiation
    def mat_pow(M, n, mod):
        if n == 1:
            return [row[:] for row in M]

        # Identity matrix
        result = [[1, 0], [0, 1]]
        base = [row[:] for row in M]

        while n > 0:
            if n % 2 == 1:
                result = mat_mult(result, base, mod)
            base = mat_mult(base, base, mod)
            n //= 2

        return result

    M = [[a, b], [c, d]]
    M_k = mat_pow(M, k, mod)

    # Sum all entries
    total = M_k[0][0] + M_k[0][1] + M_k[1][0] + M_k[1][1]

    return float(total)

